private ImmutableDictionary<string, int> _routes =
    ImmutableDictionary<string, int>.Empty;

public int Lookup(string key) => _routes[key];   // readers: no lock

public void Add(string key, int value) =>
    ImmutableInterlocked.Update(ref _routes,      // optimistic retry loop
        (map, k) => map.SetItem(k, value), key);
